const { execSync } = require('child_process');

const repoUrl = $input.first().json.body?.repoUrl || $input.first().json.repoUrl;
if (!repoUrl) throw new Error('No repoUrl provided in request body');

try {
  const cmd = `mkdir -p /tmp/web-audit-platform && cd /tmp/web-audit-platform && rm -rf repo && git clone --depth 1 ${repoUrl} repo 2>&1`;
  execSync(cmd, { encoding: 'utf-8', timeout: 60000 });
  return [{ json: { repoUrl } }];
} catch (error) {
  throw new Error(`Failed to clone repository: ${error.message}. Make sure this is a public Git repo URL (e.g. https://github.com/user/repo).`);
}

const { execSync } = require('child_process');
const repoUrl = $input.first().json.repoUrl;

let vulnerabilities = 0;
let auditData = { vulnerabilities: {} };
let auditError = null;

try {
  let foundAny = false;

  // 1. Check for Node.js (package.json)
  const nodeDirs = execSync(`find /tmp/web-audit-platform/repo -name "package.json" -not -path "*/node_modules/*" -exec dirname {} \\;`, { encoding: 'utf-8' }).split('\n').filter(Boolean);

  if (nodeDirs.length > 0) foundAny = true;

  for (const dir of nodeDirs) {
    try {
      execSync(`cd "${dir}" && npm install --package-lock-only --ignore-scripts 2>&1`, { timeout: 120000 });
      execSync(`cd "${dir}" && npm audit --json 2>&1`, { encoding: 'utf-8' });
    } catch (err) {
      if (err.stdout) {
        try {
          const parsed = JSON.parse(err.stdout);
          vulnerabilities += (parsed.metadata?.vulnerabilities?.critical || 0) + (parsed.metadata?.vulnerabilities?.high || 0);
          if (parsed.vulnerabilities) {
             Object.assign(auditData.vulnerabilities, parsed.vulnerabilities);
          }
        } catch (e) {}
      }
    }
  }

  // 2. Check for Python (requirements.txt)
  const pyDirs = execSync(`find /tmp/web-audit-platform/repo -name "requirements.txt" -not -path "*/venv/*" -exec dirname {} \\;`, { encoding: 'utf-8' }).split('\n').filter(Boolean);

  if (pyDirs.length > 0) foundAny = true;

  const pythonCmd = (() => { try { execSync('python3 --version 2>&1'); return 'python3'; } catch(e) { return 'python'; } })();

  for (const dir of pyDirs) {
    try {
      const cmd = `pip-audit -r requirements.txt -f json 2>&1`;
      execSync(`cd "${dir}" && ${cmd}`, { encoding: 'utf-8' });
    } catch (err) {
      if (err.stdout) {
        try {
          const jsonMatch = err.stdout.match(/\[.*\]/s);
          const parsed = jsonMatch ? JSON.parse(jsonMatch[0]) : JSON.parse(err.stdout);
          for (const pkg of parsed) {
             if (pkg.vulns && pkg.vulns.length > 0) {
                vulnerabilities += pkg.vulns.length;
                auditData.vulnerabilities[pkg.name] = {
                   name: pkg.name,
                   severity: 'high',
                   via: pkg.vulns.map(v => ({ title: v.aliases?.[0] || v.id }))
                };
             }
          }
        } catch (e) {}
      }
    }
  }

  if (!foundAny) {
    auditError = 'No package.json or requirements.txt found in repository';
  }

} catch (error) {
  auditError = error.message;
}

const finalAuditOutput = {
  metadata: { vulnerabilities: { critical: 0, high: vulnerabilities } },
  vulnerabilities: auditData.vulnerabilities
};

return [{ json: { repoUrl, auditOutput: finalAuditOutput, critical_vulnerabilities: vulnerabilities, auditError } }];

const { execSync } = require('child_process');

let complexityErrors = 0;
let eslintData = [];
let eslintError = null;
let parsedFiles = [];
let skippedFiles = [];

try {
  const pythonCmd = (() => { try { execSync('python3 --version 2>&1'); return 'python3'; } catch(e) { try { execSync('python --version 2>&1'); return 'python'; } catch(e2) { return null; } } })();
  if (!pythonCmd) throw new Error('Python not available in this environment');

  const cmd = `${pythonCmd} -m lizard /tmp/web-audit-platform/repo --csv -C 10 -x "*/node_modules/*" -x "*/test/*" -x "*/dist/*" -x "*/build/*" -x "*/venv/*" 2>&1 || true`;
  const output = execSync(cmd, { encoding: 'utf-8', timeout: 60000 });
  const lines = output.trim().split('\n').filter(Boolean);

  const parsedSet = new Set();
  const parseCsvLine = (line) => {
    const cells = [];
    let current = '';
    let inQuotes = false;

    for (let i = 0; i < line.length; i++) {
      const ch = line[i];
      if (ch === '"') {
        if (inQuotes && line[i + 1] === '"') {
          current += '"';
          i++;
        } else {
          inQuotes = !inQuotes;
        }
        continue;
      }
      if (ch === ',' && !inQuotes) {
        cells.push(current);
        current = '';
        continue;
      }
      current += ch;
    }

    cells.push(current);
    return cells;
  };

  for (const line of lines) {
    const parts = parseCsvLine(line);
    if (parts.length >= 8) {
      const ccn = parseInt(parts[1]);
      if (!isNaN(ccn)) {
        let filePathRaw = parts[6] ? parts[6].trim() : '';
        if (filePathRaw.includes('/repo/')) {
           filePathRaw = filePathRaw.split('/repo/').pop();
           parsedSet.add(filePathRaw);
        }
        if (ccn > 10) {
          complexityErrors++;
          eslintData.push({
            filePath: filePathRaw,
            functionName: parts[7] ? parts[7].trim() : '',
            complexity: ccn,
            line: parts[5] ? parts[5].trim() : ''
          });
        }
      }
    }
  }

  parsedFiles = Array.from(parsedSet);

  const allFilesCmd = `cd /tmp/web-audit-platform/repo && find . -type f -not -path "*/\\.git/*" -not -path "*/node_modules/*" -not -path "*/test/*" -not -path "*/dist/*" -not -path "*/build/*" -not -path "*/venv/*" | sed 's|^./||'`;
  const allFilesOutput = execSync(allFilesCmd, { encoding: 'utf-8' });
  const allFiles = allFilesOutput.trim().split('\n').filter(Boolean);

  skippedFiles = allFiles.filter(f => !parsedSet.has(f));

} catch (error) {
  eslintError = error.message;
}

const prev = $input.first().json;
return [{
  json: {
    repoUrl: prev.repoUrl,
    scannedAt: new Date().toISOString(),
    critical_vulnerabilities: prev.critical_vulnerabilities,
    auditOutput: prev.auditOutput,
    auditError: prev.auditError || null,
    complexityErrors,
    eslintData,
    parsedFiles,
    skippedFiles,
    eslintError: eslintError || null
  }
}];

const d = $input.first().json;

const vulnList = d.auditOutput?.vulnerabilities
  ? Object.values(d.auditOutput.vulnerabilities).filter(v => v.severity === 'high' || v.severity === 'critical').map(v => `- ${v.name} (${v.severity}): ${Array.isArray(v.via) ? v.via.filter(x => typeof x === 'object').map(x => x.title).join(', ') : ''}`).join('
')
  : 'None found';

const complexList = d.eslintData?.slice(0, 20).map(f => `- ${f.filePath} | ${f.functionName} | complexity: ${f.complexity}`).join('
') || 'None found';

const prompt = `You are an expert DevSecOps AI. Analyze this audit data and return your response in the EXACT following format. Do not deviate.

Repository: ${d.repoUrl}
Scanned: ${d.scannedAt}
Critical/High Vulnerabilities: ${d.critical_vulnerabilities}
Complexity Violations: ${d.complexityErrors}

Vulnerability Details:
${vulnList}

Complexity Details:
${complexList}

=== CODE QUALITY AUDIT REPORT ===
Source: ${d.repoUrl}
Scanned At: ${d.scannedAt}

--- AI EXECUTIVE SUMMARY ---
[Provide a concise executive summary assessing the codebase complexity and dependency security posture based on the provided metrics.]

--- COMPLEXITY METRICS ---
Total Violations: ${d.complexityErrors}
Overall Grade: [Assign A, B, C, D, or F based on the violations]
Functions Exceeding Limits: ${d.complexityErrors}
Top Violations: 
[List the worst complexity violations provided in the details]

--- DEPENDENCY SECURITY ---
Total Vulnerabilities (High/Critical): ${d.critical_vulnerabilities}

⚠ CRITICAL & HIGH ISSUES:
[List the specific vulnerable packages and their severity, or state 'None found' if 0]`;

return [{ json: { ...d, geminiPrompt: prompt } }];

const scanData = $node['Build Gemini Prompt'].json;
const geminiResponse = $input.first().json;

const suggestions = geminiResponse?.candidates?.[0]?.content?.parts?.[0]?.text || 'No suggestions available';

return [{ json: { ...scanData, aiSuggestions: suggestions } }];

const d = $input.first().json;
return [{ json: {
  scannedAt: d.scannedAt,
  repoUrl: d.repoUrl,
  critical_vulnerabilities: d.critical_vulnerabilities,
  complexityErrors: d.complexityErrors,
  auditError: d.auditError || '',
  eslintError: d.eslintError || ''
} }];

const d = $input.first().json;
let reportStr = JSON.stringify({
  critical_vulnerabilities: d.critical_vulnerabilities,
  auditOutput: d.auditOutput,
  complexityErrors: d.complexityErrors,
  eslintData: d.eslintData,
  auditError: d.auditError,
  eslintError: d.eslintError,
  aiSuggestions: d.aiSuggestions
});
if (reportStr.length > 48000) {
  reportStr = reportStr.substring(0, 48000) + '... [TRUNCATED]';
}
return [{ json: {
  scannedAt: d.scannedAt,
  repoUrl: d.repoUrl,
  fullReport: reportStr
} }];
